import{Z as t,e as s,f as i,a0 as a}from"./chunks/framework.DmpHOl9T.js";const m=JSON.parse('{"title":"Stencils for Repeatable Form Types","description":"","frontmatter":{},"headers":[],"relativePath":"guides/control-panel-admin/stencils-for-repeatable-form-types.md","filePath":"guides/control-panel-admin/stencils-for-repeatable-form-types.md","lastUpdated":1782532814000}'),n={name:"guides/control-panel-admin/stencils-for-repeatable-form-types.md"};function o(r,e,l,d,c,p){return s(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="stencils-for-repeatable-form-types" tabindex="-1">Stencils for Repeatable Form Types <a class="header-anchor" href="#stencils-for-repeatable-form-types" aria-label="Permalink to &quot;Stencils for Repeatable Form Types&quot;">​</a></h1><p>Stencils are reusable starter forms — layout, notifications, integrations, and settings included. They help teams spin up consistent enquiry, application, or survey forms without rebuilding the same field tree every time. This walkthrough builds a stencil, wires synced fields, and deploys it across environments.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/forms/stencils">Stencils</a></li><li><a href="/forms/synced-fields">Synced Fields</a> (optional but recommended)</li><li><strong>Access stencils</strong> permission for authors who should manage stencils</li></ul><h2 id="stencils-vs-live-forms" tabindex="-1">Stencils vs Live Forms <a class="header-anchor" href="#stencils-vs-live-forms" aria-label="Permalink to &quot;Stencils vs Live Forms&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Stencil</th><th>Form created from stencil</th></tr></thead><tbody><tr><td>Purpose</td><td>Starting template</td><td>Live, editable form</td></tr><tr><td>Changes affect</td><td>Future forms only</td><td>That form&#39;s submissions</td></tr><tr><td>Storage</td><td>CP stencils + optional project config</td><td>Database</td></tr></tbody></table><p>Treat stencils as starting points, not shared live forms.</p><h2 id="step-1-—-build-the-canonical-enquiry-stencil" tabindex="-1">Step 1 — Build the Canonical Enquiry Stencil <a class="header-anchor" href="#step-1-—-build-the-canonical-enquiry-stencil" aria-label="Permalink to &quot;Step 1 — Build the Canonical Enquiry Stencil&quot;">​</a></h2><ol><li>Go to <strong>Formie → Stencils</strong></li><li>Click <strong>New stencil</strong></li><li>Name it <code>Enquiry Form</code> (handle <code>enquiryForm</code>)</li><li>Build the layout you want every enquiry to start with: <ul><li>Name, Email, Phone, Message fields</li><li>Admin notification + submitter confirmation</li><li>Turnstile captcha enabled</li><li>Ajax submit, success message</li></ul></li></ol><p>Save the stencil.</p><h2 id="step-2-—-add-synced-fields" tabindex="-1">Step 2 — Add Synced Fields <a class="header-anchor" href="#step-2-—-add-synced-fields" aria-label="Permalink to &quot;Step 2 — Add Synced Fields&quot;">​</a></h2><p>For fields that must stay identical across every form — consent checkbox, privacy policy link, UTM hidden fields — use <a href="/forms/synced-fields">synced fields</a>:</p><ol><li>Create the shared field definition once (<strong>Formie → Synced Fields</strong>)</li><li>While editing the stencil, add the field as a <strong>synced field</strong> placement (not a one-off copy)</li></ol><p>When someone creates a form from the stencil, Formie adds a placement pointing at the same shared definition. Update the definition once; all forms update.</p><p>If a shared definition is missing on an environment (handle not deployed yet), Formie falls back to an independent field copy from the stencil snapshot.</p><h2 id="step-3-—-set-default-stencil-for-new-forms" tabindex="-1">Step 3 — Set Default Stencil for New Forms <a class="header-anchor" href="#step-3-—-set-default-stencil-for-new-forms" aria-label="Permalink to &quot;Step 3 — Set Default Stencil for New Forms&quot;">​</a></h2><p>Developers can auto-apply a stencil when authors create forms without picking one:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;*&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;defaultFormStencil&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;enquiryForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Authors can still choose a different stencil or start blank from the <strong>New Form</strong> dialog.</p><h2 id="step-4-—-create-forms-from-the-stencil" tabindex="-1">Step 4 — Create Forms from the Stencil <a class="header-anchor" href="#step-4-—-create-forms-from-the-stencil" aria-label="Permalink to &quot;Step 4 — Create Forms from the Stencil&quot;">​</a></h2><ol><li><strong>Formie → Forms → New Form</strong></li><li>Pick <strong>Enquiry Form</strong> stencil</li><li>Customise title, handle, and any form-specific copy</li><li>Save</li></ol><p>The result is an independent form. Editing the stencil later does not change existing forms — only forms created after the stencil change (unless you manually re-import or rebuild).</p><h2 id="step-5-—-save-an-existing-form-as-a-stencil" tabindex="-1">Step 5 — Save an Existing Form as a Stencil <a class="header-anchor" href="#step-5-—-save-an-existing-form-as-a-stencil" aria-label="Permalink to &quot;Step 5 — Save an Existing Form as a Stencil&quot;">​</a></h2><p>From the form builder on any live form:</p><ol><li>Open the form menu</li><li>Choose <strong>Save as stencil</strong></li><li>Name the new stencil</li></ol><p>Useful when a one-off form became the de facto standard and you want to codify it.</p><h2 id="step-6-—-project-stencils-developers" tabindex="-1">Step 6 — Project Stencils (Developers) <a class="header-anchor" href="#step-6-—-project-stencils-developers" aria-label="Permalink to &quot;Step 6 — Project Stencils (Developers)&quot;">​</a></h2><p>For starter kits versioned with the site, create <strong>project stencils</strong> stored in project config:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/project/formie/stencils/…</span></span></code></pre></div><p>Project stencils:</p><ul><li>Require admin changes enabled to create/edit in CP (typically local/staging)</li><li>Are <strong>view-only</strong> on production when admin changes are disabled</li><li>Support <strong>Save a copy</strong> to fork into an editable CP stencil</li></ul><p>Handles must be unique across regular and project stencils.</p><p>On deploy, project stencils appear in the <strong>New Form</strong> stencil picker alongside CP stencils.</p><h2 id="step-7-—-combine-with-form-groups" tabindex="-1">Step 7 — Combine with Form Groups <a class="header-anchor" href="#step-7-—-combine-with-form-groups" aria-label="Permalink to &quot;Step 7 — Combine with Form Groups&quot;">​</a></h2><p>Assign new enquiry forms to a <strong>Marketing</strong> <a href="/forms/form-groups">form group</a> for sidebar organisation and group defaults. Stencils define structure; groups define CP policies and defaults.</p><p>See <a href="/guides/control-panel-admin/form-groups-and-defaults-at-scale">Form groups and defaults at scale</a>.</p><h2 id="step-8-—-deploy-across-environments" tabindex="-1">Step 8 — Deploy Across Environments <a class="header-anchor" href="#step-8-—-deploy-across-environments" aria-label="Permalink to &quot;Step 8 — Deploy Across Environments&quot;">​</a></h2><p>Project stencils travel via <code>project-config/sync</code>. CP-created stencils are database content — export/import them with <a href="/guides/control-panel-admin/import-and-export-between-environments">Import and export between environments</a> or include them in your content migration process.</p><p>Order of operations on a fresh environment:</p><ol><li>Deploy project config (project stencils, synced field definitions, form groups)</li><li>Import or sync CP stencils if needed</li><li>Verify synced field handles resolve before authors create forms from stencils</li></ol><h2 id="included-default" tabindex="-1">Included Default <a class="header-anchor" href="#included-default" aria-label="Permalink to &quot;Included Default&quot;">​</a></h2><p>Formie ships a <code>Contact Form</code> stencil as a general starting point. Replace or extend it for your project&#39;s conventions.</p>`,42)])])}const f=t(n,[["render",o]]);export{m as __pageData,f as default};
